  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_dict = {node['id']: node for node in nodes}
    children = {}
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children.setdefault(pid, []).append(node['id'])
    # validate required symbols exist
    all_symbols = {node['symbol'] for node in nodes}
    if not required_symbols.issubset(all_symbols):
        raise ValueError('Required symbols not all present in initial nodes')
    # initial retained set
    retained = set(node_dict.keys())
    if 'root' not in retained:
        raise ValueError('No root node')
    # check root has parent None
    root_node = node_dict['root']
    if root_node['parent'] is not None:
        raise ValueError('Root node has a parent')
    # sort nodes by depth descending, then by id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removal_order = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if node['parent'] is None:
            continue
        # check if node has retained children
        node_children = children.get(nid, [])
        has_retained_children = any(cid in retained for cid in node_children)
        if has_retained_children:
            continue
        # tentatively remove
        retained.discard(nid)
        # check required symbols still represented
        symbols_after = set()
        for rid in retained:
            symbols_after.add(node_dict[rid]['symbol'])
        if required_symbols.issubset(symbols_after):
            removal_order.append(nid)
        else:
            retained.add(nid)  # revert
    # sort retained ids
    sorted_retained = sorted(retained)
    return {'retained_ids': sorted_retained, 'removal_order': removal_order}
